// src/websocket.ts
import SockJS from 'sockjs-client';
import { Client, over } from 'stompjs';
import { WebSocketMessage } from './models/WebSocketMessage';
import { Task } from './models/Task';

let stompClient: Client | null = null;
let connected = false;
let connecting = false;
let reconnectAttempts = 0;
const MAX_RECONNECT_ATTEMPTS = 10;
const RECONNECT_DELAY_BASE = 1000; // Start with 1 second delay
const subscribers: { [key: string]: ((data: any) => void)[] } = {};
const pendingMessages: { destination: string, message: any }[] = [];
// Keep track of subscription IDs to prevent duplicates
const activeSubscriptionIds: Set<string> = new Set();
const SOCKET_URL = 'http://localhost:8080/ws';

export const connectWebSocket = () => {
  // Don't attempt to connect if we're already connected or in the process of connecting
  if ((stompClient && stompClient.connected) || connecting) {
    return;
  }

  connecting = true;

  try {
    const socket = new SockJS(SOCKET_URL);
    stompClient = over(socket);
    stompClient.debug = () => {}; // Disable debug logs

    // Add event handlers for underlying socket
    if (socket) {
      socket.onclose = () => {
        console.log('SockJS socket closed');
        connected = false;
        connecting = false;
        // Try to reconnect after delay
        setTimeout(connectWebSocket, 5000);
      };

      socket.onerror = (error) => {
        console.error('SockJS socket error:', error);
      };
    }

    stompClient.connect({}, 
      // Success callback
      (frame) => {
        console.log('WebSocket connected successfully');
        connected = true;
        connecting = false;

        // Small delay to ensure connection is fully established before subscribing
        setTimeout(() => {
          // Only subscribe when we're sure the connection is established
          subscribeToTopics();

          // Send any pending messages
          processPendingMessages();
        }, 500);
      }, 
      // Error callback
      (error) => {
        console.error('WebSocket connection error:', error);
        connected = false;
        connecting = false;

        // Reconnect after delay
        setTimeout(connectWebSocket, 5000);
      }
    );
  } catch (err) {
    console.error('Error initializing WebSocket:', err);
    connected = false;
    connecting = false;
    setTimeout(connectWebSocket, 5000);
  }
};

// Extract subscription logic to a separate function
const subscribeToTopics = () => {
  if (!stompClient || !stompClient.connected) {
    console.log('Deferring subscriptions until connection is established');
    // Don't error here as we'll retry later
    return;
  }

  try {
    // Keep track of active subscriptions to avoid duplicates
    const activeSubscriptions = stompClient.subscriptions || {};

    if (!activeSubscriptionIds.has('/topic/tasks')) {
      stompClient.subscribe('/topic/tasks', (message) => {
        const tasks: Task[] = JSON.parse(message.body);
        notifySubscribers('tasks', tasks);
        activeSubscriptionIds.add('/topic/tasks');
      });
    }

    if (!activeSubscriptionIds.has('/topic/users')) {
      stompClient.subscribe('/topic/users', (message) => {
        const users = JSON.parse(message.body);
        notifySubscribers('users', users);
        activeSubscriptionIds.add('/topic/users');
      });
    }

    if (!activeSubscriptionIds.has('/topic/messages')) {
      stompClient.subscribe('/topic/messages', (message) => {
        const webSocketMessage: WebSocketMessage = JSON.parse(message.body);
        notifySubscribers('messages', webSocketMessage);
        activeSubscriptionIds.add('/topic/messages');
      });
    }
  } catch (error) {
    console.error('Error subscribing to topics:', error);
    // Force reconnection if subscription fails, but with a delay
    disconnectWebSocket();
    setTimeout(connectWebSocket, 1000);
  }
};

// Extract the message processing to a separate function
const processPendingMessages = () => {
  while (pendingMessages.length > 0) {
    const pending = pendingMessages.shift();
    if (pending) {
      sendMessage(pending.destination, pending.message);
    }
  }
};

export const disconnectWebSocket = () => {
  if (stompClient) {
    try {
      if (stompClient.connected) {
        stompClient.disconnect(() => {
          console.log('WebSocket disconnected');
          connected = false;
        });
      } else {
        // Reset client if it exists but isn't connected
        stompClient = null;
        connected = false;
      }
    } catch (error) {
      console.error('Error disconnecting WebSocket:', error);
      stompClient = null;
      connected = false;
    }
  }
};

export const sendMessage = (destination: string, message: any) => {
  if (stompClient && stompClient.connected) {
    try {
      stompClient.send(destination, {}, JSON.stringify(message));
    } catch (error) {
      console.error('Error sending message:', error);
      pendingMessages.push({ destination, message });
      // Attempt to reconnect since the send failed
      disconnectWebSocket();
      connectWebSocket();
    }
  } else {
    console.log('WebSocket not connected yet, queuing message');
    pendingMessages.push({ destination, message });
    connectWebSocket(); // Try to connect
  }
};

export const subscribe = (topic: string, callback: (data: any) => void) => {
  if (!subscribers[topic]) {
    subscribers[topic] = [];
  }
  subscribers[topic].push(callback);

  // Always initiate a connection if not already connected
  if (!connected || !stompClient || !stompClient.connected) {
    connectWebSocket();
  }

  // Return unsubscribe function
  return () => {
    subscribers[topic] = subscribers[topic].filter(cb => cb !== callback);
  };
};

const notifySubscribers = (topic: string, data: any) => {
  if (subscribers[topic]) {
    subscribers[topic].forEach(callback => callback(data));
  }
};
